return (res) => {
  try {
    const norm = (s) => String(s || '').replace(/\s+/g, '');
    if (String(res.type || '') === 'completion' && res.answer) {
      const probe = norm(res.question).slice(0, 24);
      const roots = Array.from(document.querySelectorAll('.questionLi'));
      const root = roots.find((el) => norm(el.textContent).includes(probe));
      if (root) {
        const n = root.querySelectorAll('.answerBg .answer_p, .textDIV, .eidtDiv').length;
        let text = String(res.answer);
        try {
          const arr = JSON.parse(text);
          if (Array.isArray(arr)) text = String(arr[arr.length - 1] || '');
        } catch (e) {}
        if (n >= 2 && text) {
          const pieces = new Array(n - 1).fill('（略）');
          pieces.push(text);
          return [res.question, JSON.stringify(pieces)];
        }
      }
    }
  } catch (e) {}
  return [res.question, res.answer];
};
